WFJ.Data.add("book", {
  ["ff4afaa2978faf3e"] = { "同時に、Lieutenant AlveroldをKalimdor大陸を巡る探検任務に派遣する。彼の部隊は任務を完了した後、Tiragarde Keepで我が軍と合流すること。\n\nLieutenant Alveroldの任務はかなり長期に及ぶと予想される。新たな地は広大で危険なようだ。だが、私かBenedictの身に不幸が降りかかった場合は、Alveroldの部隊が砦を奪還する。\n\nあの要塞が我らのものとなるまで、何度でも部隊を送り込むのだ！\n\n--Admiral Proudmoore", "." },
  ["ff6f142aa71b41a0"] = { "墓地の番人の三人組の目に留まった。彼らが取り押さえようとすると、Morganは彼らに矛先を向け、罪のない番人たちに罪を着せる言葉を浴びせ、そして全員を殺した。\n\nやがて怒りが過ぎ去ると、Morganの心に理解が忍び寄り、彼は番人の一人の胸に突き立てられた血まみれの剣を目にした。感情によって限界まで追い詰められた彼は、腰のナイフを抜き、自らの心臓に突き立てた。\n\nMorgan Ladimoreの遺体と、3人の犠牲者の遺体が発見されたのは、", "." },
  ["ff7db1b1640d349f"] = { "Ashenvaleを救うための私の探求について記録を残すため、この日誌をつけ始めた。少し前に起きた出来事のいくつかには謎があり、同胞を助けるために、その一部でも解き明かせればと願っている。\n\n後になって忘れてしまわないよう、まず事実を書き留めておこう。\n\n最近、魔法使いDartolの企てについての噂が真実であることを突き止めた。", "." },
  ["ff92685980ff6416"] = { "エルフから魔法の道を教わった最初の100人の魔術師たちは、その力を広げ、呪文を紡ぐ神秘の技をはるかに詳しく研究した。もともと強い意志と高潔な精神を理由に選ばれたこの魔術師たちは、常に慎重かつ責任をもって魔法を行使してきた。しかし彼らは、戦争の厳しさも自制の必要性も知らない新しい世代に、その秘密と力を伝えてしまった。", "." },
  ["ffa42d5f2e68fbce"] = { "（染みのせいで、日誌の一部しか読めない。）\n\nUldaman、3日目\n\n自分がなんと愚かだったか、信じられない。忌まわしいShadowforgeのドワーフどもに不意を突かれるとは、新米のような失態だ。傷の治りが遅い。きっと毒にやられているのだ。力が抜けていくのを感じる。それでも先を偵察しなければ……\n\n……さらに悪いことに、あのノームが私のために作ってくれた首飾りが砕けてしまった！ はめ込まれていた最も大きな宝石のうち3つが失われた。見つけなければならない。それがなければ首飾りには何の力もない……", "." },
